#!/usr/bin/env python3
"""
라벨 엑셀 가져오기 테스트용 픽스처 만들기 (tests/core/labels/xlsxImport.test.ts).

양식 원본(계획_라벨링/기록양식_v1.xlsx · 기록양식_v1_대조용.xlsx)은 읽기만 하고, 값을 채운 사본을 이 폴더에 씁니다.
칸은 머리글 글자로 찾습니다(columns.ts 머리글). 값은 시험용으로 지어낸 것이고 실제 판독 결과가 아닙니다.

다시 만들기 (app/ 에서, python3 + openpyxl 3.1):
  python3 tests/fixtures/labels/make_fixtures.py
양식을 다시 만든 뒤(scripts/label-template/README.md)에는 이 스크립트도 다시 돌립니다.
"""
from __future__ import annotations

import sys
from datetime import datetime
from pathlib import Path

from openpyxl import load_workbook

HERE = Path(__file__).resolve().parent
TOOL_ROOT = HERE.parents[3]  # 10_데이터관리툴
BLIND = TOOL_ROOT / '계획_라벨링' / '기록양식_v1.xlsx'
RECON = TOOL_ROOT / '계획_라벨링' / '기록양식_v1_대조용.xlsx'

F1 = '12T-SV-01-Cap on.nde'
F2 = '12T-SV-02-Cap on.nde'
F3 = '12T-SV-03-Cap off.nde'
F4 = '12T-SV-04-Cap on.nde'
F2_DEVICE = '12T-SV-PL23840-i15-CAP20'  # 장비 원본 파일명 (ModelSetup SaveFileName)

S90 = '섹토리얼 Skew 90'
S270 = '섹토리얼 Skew 270'


def col_of(ws, header: str) -> int:
    for c in range(1, ws.max_column + 1):
        if ws.cell(row=1, column=c).value == header:
            return c
    raise SystemExit(f"'{ws.title}' 시트에 머리글 '{header}' 가 없습니다. 양식이 바뀌었으면 이 스크립트를 고칩니다.")


def fill(ws, row: int, values: dict) -> None:
    for header, v in values.items():
        ws.cell(row=row, column=col_of(ws, header), value=v)


def reader(wb, labeler: str | None, qualification: str | None = 'UT Level II') -> None:
    ws = wb['판독자']
    fill(ws, 2, {'라벨러 ID': labeler, '자격': qualification})


