        {**ok, '지시 번호': 'E2', '기록 구분': '결함임'},  # 3: 잘못된 열거값
        {**ok, '지시 번호': 'E3', '그룹 (기법·Skew)': '리니어 Skew 90'},  # 4: 그룹 없음
