        {**ok, '지시 번호': 'E5', '스캔 끝 (mm)': 20},  # 6: 끝 < 시작
        {**ok, '지시 번호': 'E6', '실제 깊이 아래 (mm)': 15},  # 7: 두께(12)보다 깊음
        {**ok, '지시 번호': 'E7', '기록 구분': '형상 불완전', '결함 종류': None},  # 8: 형상 불완전 세부 빔
        {**ok, '지시 번호': 'E8'},  # 9: 바른 줄
        {**ok, '지시 번호': 'E8', '스캔 시작 (mm)': 50, '스캔 끝 (mm)': 60},  # 10: 지시 번호 겹침
