def no_labeler() -> None:
    wb = load_workbook(BLIND)  # 판독자 시트의 라벨러 ID 를 비워 둔 그대로
    fill(wb['지시'], 2, {'파일명': F1, '지시 번호': '1', '기록 구분': '결함', '스캔 시작 (mm)': 1, '스캔 끝 (mm)': 2,
                         '존재 확신도': '확실'})
    wb.save(HERE / 'x3_no_labeler.xlsx')


def bad_header() -> None:
    wb = load_workbook(BLIND)
    reader(wb, 'kim-l2')
    ws = wb['지시']
    ws.cell(row=1, column=col_of(ws, '스캔 시작 (mm)'), value='스캔 시작')
    wb.save(HERE / 'x3_bad_header.xlsx')


def main() -> int:
    for p in (BLIND, RECON):
        if not p.exists():
            print(f'양식이 없습니다: {p}', file=sys.stderr)
            return 1
    blind_filled()
    reconciled_filled()
    errors_filled()
    no_labeler()
    bad_header()
    print('저장:', ', '.join(sorted(p.name for p in HERE.glob('*.xlsx'))))
    return 0


if __name__ == '__main__':
    sys.exit(main())
